      "path": "ChatMachines/GeminiSupervisor/scripts/sync-readers.js",
      "purpose": "Deterministic stable-reader projection generator that preserves full document content and tracks provenance",
      "content": "const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { execSync } = require('child_process');

const ROOT_DIR = path.resolve(__dirname, '../../..');
const DEP_MAP_PATH = path.join(ROOT_DIR, 'ChatMachines/GeminiSupervisor/dependency-map.json');

function getGitBlobSha(filePath) {
  try {
    return execSync(`git hash-object "${filePath}"`, { encoding: 'utf8', cwd: ROOT_DIR }).trim();
  } catch (err) {
    const fileBuffer = fs.readFileSync(filePath);
    const header = Buffer.from(`blob ${fileBuffer.length}\0`);
    return crypto.createHash('sha1').update(Buffer.concat([header, fileBuffer])).digest('hex');
  }
}

function getHeadCommitSha() {
  try {
    return execSync('git rev-parse HEAD', { encoding: 'utf8', cwd: ROOT_DIR }).trim();
  } catch (err) {
    return 'HEAD_UNKNOWN';
  }
}

function parseMarkdownToRecords(content) {
  const lines = content.split(/\r?\n/);
  const records = [];
  let currentTopic = null;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const headingMatch = line.match(/^(#{1,6})\s+(.+)$/);
    if (headingMatch) {
      currentTopic = headingMatch[2].trim();
    }
    records.push({
      index: i,
      topic: currentTopic,
      text: line
    });
  }
  return records;
}

function parseJsonToRecords(content) {
  const parsed = JSON.parse(content);
  if (Array.isArray(parsed)) {
    return parsed.map((item, idx) => ({
      index: idx,
      topic: `item_${idx}`,
      value: item
    }));
  } else if (typeof parsed === 'object' && parsed !== null) {
    const keys = Object.keys(parsed);
    return keys.map((key, idx) => ({
      index: idx,
      topic: key,
      value: parsed[key]
    }));
  }
  return [{ index: 0, topic: 'scalar', value: parsed }];
}

function syncAll() {
  if (!fs.existsSync(DEP_MAP_PATH)) {
    console.error(`Dependency map not found at ${DEP_MAP_PATH}`);
    process.exit(1);
  }

  const depMap = JSON.parse(fs.readFileSync(DEP_MAP_PATH, 'utf8'));
  const commitSha = getHeadCommitSha();
  let updated = false;

  for (const [docKey, entry] of Object.entries(depMap.mappings)) {
    const canonicalFullPath = path.join(ROOT_DIR, entry.canonical_path);
    const readerFullPath = path.join(ROOT_DIR, entry.stable_reader_path);

    if (!fs.existsSync(canonicalFullPath)) {
      console.warn(`Canonical source missing: ${entry.canonical_path}`);
      continue;
    }

    const currentSourceBlob = getGitBlobSha(canonicalFullPath);
    const rawContent = fs.readFileSync(canonicalFullPath, 'utf8');
    const isJson = entry.canonical_path.endsWith('.json');
    const records = isJson ? parseJsonToRecords(rawContent) : parseMarkdownToRecords(rawContent);

    const projection = {
      doc_id: docKey,
      canonical_path: entry.canonical_path,
      source_blob_sha: currentSourceBlob,
      item_count: records.length,
      generated_at: new Date().toISOString(),
      records: records
    };

    const projectionJson = JSON.stringify(projection, null, 2);
    fs.mkdirSync(path.dirname(readerFullPath), { recursive: true });
    fs.writeFileSync(readerFullPath, projectionJson, 'utf8');

    const currentReaderBlob = getGitBlobSha(readerFullPath);
    if (entry.source_blob_sha !== currentSourceBlob || entry.reader_blob_sha !== currentReaderBlob) {
      entry.source_blob_sha = currentSourceBlob;
      entry.source_commit_sha = commitSha;
      entry.reader_blob_sha = currentReaderBlob;
      entry.item_count = records.length;
      entry.last_synced_at = new Date().toISOString();
      updated = true;
    }
  }

  if (updated) {
    fs.writeFileSync(DEP_MAP_PATH, JSON.stringify(depMap, null, 2) + '\n', 'utf8');
    const sentinelPath = path.join(ROOT_DIR, depMap.sentinel_file);
    fs.mkdirSync(path.dirname(sentinelPath), { recursive: true });
    fs.writeFileSync(sentinelPath, `SYNCED=${new Date().toISOString()}\nCOMMIT=${commitSha}\n`, 'utf8');
    console.log('Successfully synced stable readers and updated dependency map.');
  } else {
    console.log('All readers are up-to-date.');
  }
}

if (require.main === module) {
  syncAll();
}

module.exports = { syncAll, parseMarkdownToRecords, parseJsonToRecords };"
