      "path": "ChatMachines/GeminiSupervisor/scripts/truth-challenge-engine.js",
      "purpose": "Deterministic engine for nonce-scoped truth-reader challenge creation, randomized distributed damage, and worker repair verification",
      "content": "const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const assert = require('assert');

const ROOT_DIR = path.resolve(__dirname, '../../..');
const DEP_MAP_PATH = path.join(ROOT_DIR, 'ChatMachines/GeminiSupervisor/dependency-map.json');
const PLACEHOLDER_KEY = '^MISSING_KEY^';
const PLACEHOLDER_VALUE = '^MISSING_VALUE^';

function secureRandomInt(min, max) {
  const range = max - min;
  if (range <= 0) return min;
  const randomBuffer = crypto.randomBytes(4);
  const randomValue = randomBuffer.readUInt32BE(0);
  return min + (randomValue % range);
}

function selectDistributedIndices(totalCount, damageRate = 0.1) {
  const targetDamageCount = Math.max(1, Math.round(totalCount * damageRate));
  const bandCount = Math.min(targetDamageCount, Math.floor(totalCount / 3) || 1);
  const bandSize = totalCount / bandCount;
  const selected = new Set();

  for (let b = 0; b < bandCount; b++) {
    const start = Math.floor(b * bandSize);
    const end = Math.floor((b + 1) * bandSize);
    const picked = secureRandomInt(start, end);
    selected.add(picked);
  }

  while (selected.size < targetDamageCount && selected.size < totalCount) {
    const idx = secureRandomInt(0, totalCount);
    selected.add(idx);
  }
  return Array.from(selected).sort((a, b) => a - b);
}

function createDamagedProjection(intactProjection, runNonce) {
  const damaged = JSON.parse(JSON.stringify(intactProjection));
  damaged.run_nonce = runNonce;
  damaged.challenge_type = 'repair_required';
  damaged.placeholder_marker = { key: PLACEHOLDER_KEY, value: PLACEHOLDER_VALUE };

  const records = damaged.records;
  const damagedIndices = selectDistributedIndices(records.length, 0.10);

  for (const idx of damagedIndices) {
    records[idx] = {
      index: idx,
      topic: PLACEHOLDER_KEY,
      damaged: true,
      text: PLACEHOLDER_VALUE,
      value: PLACEHOLDER_VALUE
    };
  }

  damaged.damaged_indices_count = damagedIndices.length;
  return { damaged, damagedIndices };
}

function initializeRunChallenges(runNonce, selectedDocIds) {
  if (!fs.existsSync(DEP_MAP_PATH)) {
    throw new Error(`Dependency map not found: ${DEP_MAP_PATH}`);
  }
  const depMap = JSON.parse(fs.readFileSync(DEP_MAP_PATH, 'utf8'));
  const runDir = path.join(ROOT_DIR, 'ChatMachines/GeminiSupervisor/runs', runNonce);
  const truthDir = path.join(runDir, 'truth-reader');
  const baselineDir = path.join(truthDir, '.baseline');

  fs.mkdirSync(truthDir, { recursive: true });
  fs.mkdirSync(baselineDir, { recursive: true });

  const manifest = {
    run_nonce: runNonce,
    created_at: new Date().toISOString(),
    status: 'PENDING_WORKER_REPAIR',
    documents: {}
  };

  for (const docId of selectedDocIds) {
    const mapping = depMap.mappings[docId];
    if (!mapping) {
      throw new Error(`Unrecognized document selector: ${docId}`);
    }
    const stableReaderFullPath = path.join(ROOT_DIR, mapping.stable_reader_path);
    if (!fs.existsSync(stableReaderFullPath)) {
      throw new Error(`Stable reader not found at: ${stableReaderFullPath}`);
    }

    const stableReader = JSON.parse(fs.readFileSync(stableReaderFullPath, 'utf8'));
    const fullProjection = JSON.parse(JSON.stringify(stableReader));
    fullProjection.run_nonce = runNonce;
    fullProjection.provenance = {
      canonical_path: mapping.canonical_path,
      source_blob_sha: mapping.source_blob_sha,
      source_commit_sha: mapping.source_commit_sha,
      reader_blob_sha: mapping.reader_blob_sha,
      last_synced_at: mapping.last_synced_at
    };

    const { damaged } = createDamagedProjection(fullProjection, runNonce);

    const fullDocPath = path.join(truthDir, `${docId}.full.json`);
    const repairDocPath = path.join(truthDir, `${docId}.repair.json`);
    const baselineDocPath = path.join(baselineDir, `${docId}.damaged.json`);

    fs.writeFileSync(fullDocPath, JSON.stringify(fullProjection, null, 2), 'utf8');
    fs.writeFileSync(repairDocPath, JSON.stringify(damaged, null, 2), 'utf8');
    fs.writeFileSync(baselineDocPath, JSON.stringify(damaged, null, 2), 'utf8');

    manifest.documents[docId] = {
      full_path: path.relative(ROOT_DIR, fullDocPath),
      repair_path: path.relative(ROOT_DIR, repairDocPath),
      item_count: fullProjection.records.length,
      damaged_count: damaged.damaged_indices_count
    };
  }

  fs.writeFileSync(path.join(truthDir, 'manifest.json'), JSON.stringify(manifest, null, 2), 'utf8');
  return manifest;
}

function containsGenericPlaceholders(obj) {
  const str = JSON.stringify(obj);
  return str.includes(PLACEHOLDER_KEY) || str.includes(PLACEHOLDER_VALUE);
}

function normalizeForComparison(obj) {
  const clone = JSON.parse(JSON.stringify(obj));
  delete clone.challenge_type;
  delete clone.placeholder_marker;
  delete clone.damaged_indices_count;
  if (Array.isArray(clone.records)) {
    for (const r of clone.records) {
      delete r.damaged;
    }
  }
  return clone;
}

function verifyRunRepairs(runNonce) {
  const truthDir = path.join(ROOT_DIR, 'ChatMachines/GeminiSupervisor/runs', runNonce, 'truth-reader');
  const baselineDir = path.join(truthDir, '.baseline');
  const manifestPath = path.join(truthDir, 'manifest.json');

  if (!fs.existsSync(manifestPath)) {
    throw new Error(`Truth reader manifest not found for run ${runNonce}`);
  }

  const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
  const results = { pass: true, mismatches: [] };

  for (const [docId, meta] of Object.entries(manifest.documents)) {
    const fullDocPath = path.join(truthDir, `${docId}.full.json`);
    const repairDocPath = path.join(truthDir, `${docId}.repair.json`);
    const baselineDocPath = path.join(baselineDir, `${docId}.damaged.json`);

    if (!fs.existsSync(repairDocPath)) {
      results.pass = false;
      results.mismatches.push(`${docId}: repair file missing`);
      continue;
    }

    let fullContent, repairContent;
    try {
      fullContent = JSON.parse(fs.readFileSync(fullDocPath, 'utf8'));
      repairContent = JSON.parse(fs.readFileSync(repairDocPath, 'utf8'));
    } catch (e) {
      results.pass = false;
      results.mismatches.push(`${docId}: parse error in repair JSON`);
      continue;
    }

    if (containsGenericPlaceholders(repairContent)) {
      results.pass = false;
      results.mismatches.push(`${docId}: generic placeholders still present`);
      continue;
    }

    const normFull = normalizeForComparison(fullContent);
    const normRepair = normalizeForComparison(repairContent);

    try {
      assert.deepStrictEqual(normRepair, normFull);
    } catch (err) {
      results.pass = false;
      results.mismatches.push(`${docId}: repaired content does not match intact projection`);
      if (fs.existsSync(baselineDocPath)) {
        fs.copyFileSync(baselineDocPath, repairDocPath);
      }
    }
  }

  if (results.pass) {
    const passRecord = {
      run_nonce: runNonce,
      verified_at: new Date().toISOString(),
      status: 'PASS',
      verified_documents: Object.keys(manifest.documents)
    };
    fs.writeFileSync(path.join(truthDir, 'PASS.json'), JSON.stringify(passRecord, null, 2), 'utf8');
    if (fs.existsSync(baselineDir)) {
      fs.rmSync(baselineDir, { recursive: true, force: true });
    }
    for (const docId of Object.keys(manifest.documents)) {
      const repairPath = path.join(truthDir, `${docId}.repair.json`);
      if (fs.existsSync(repairPath)) {
        fs.unlinkSync(repairPath);
      }
    }
    manifest.status = 'COMPLETED_PASS';
    manifest.verified_at = passRecord.verified_at;
    fs.writeFileSync(manifestPath, JSON.stringify(manifest, null, 2), 'utf8');
    return { success: true, passRecord };
  } else {
    return { success: false, errors: results.mismatches };
  }
}

module.exports = {
  selectDistributedIndices,
  createDamagedProjection,
  initializeRunChallenges,
  verifyRunRepairs,
  normalizeForComparison
};"
