      "purpose": "Deterministic generator for Step 0 input form with pre-populated system fields and enumerated document selectors",
      "content": "const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const ROOT_DIR = path.resolve(__dirname, '../../..');
const DEP_MAP_PATH = path.join(ROOT_DIR, 'ChatMachines/GeminiSupervisor/dependency-map.json');

function generateStep0Form(userRequest, existingNonce = null) {
  const runNonce = existingNonce || crypto.randomBytes(8).toString('hex');
  const depMap = JSON.parse(fs.readFileSync(DEP_MAP_PATH, 'utf8'));

  const selectableDocs = {};
  for (const docKey of Object.keys(depMap.mappings)) {
    selectableDocs[docKey] = false;
  }

  const form = {
    system_locked: {
      step_number: 0,
      role: 'Worker',
      run_nonce: runNonce,
      verbatim_user_request: userRequest || '',
      form_generated_at: new Date().toISOString(),
      selectable_document_universe: Object.keys(depMap.mappings)
    },
    worker_editable: {
      task_understanding: '',
      execution_plan: '',
      document_selection: selectableDocs
    },
    form_status: 'AWAITING_WORKER_INPUT'
  };

  const runDir = path.join(ROOT_DIR, 'ChatMachines/GeminiSupervisor/runs', runNonce);
  fs.mkdirSync(runDir, { recursive: true });
  const formPath = path.join(runDir, 'step-0-form.json');
  fs.writeFileSync(formPath, JSON.stringify(form, null, 2), 'utf8');

  return { runNonce, formPath, form };
}

if (require.main === module) {
  const userReq = process.argv[2] || 'Default maintenance run';
  const nonce = process.argv[3] || null;
  const res = generateStep0Form(userReq, nonce);
  console.log(`Generated Step 0 form for run ${res.runNonce} at ${res.formPath}`);
}

module.exports = { generateStep0Form };"
