    {
      "path": ".github/workflows/truth-reader-repair.yml",
      "purpose": "GitHub Actions workflow orchestrating Step 0 challenge creation and deterministic worker repair verification",
      "content": "name: Truth Reader Repair Gate

on:
  push:
    paths:
      - 'ChatMachines/GeminiSupervisor/runs/**'
      - 'ChatMachines/GeminiSupervisor/dependency-map.json'

permissions:
  contents: write

jobs:
  truth-reader-gate:
    runs-on: ubuntu-latest
    if: github.actor != 'github-actions[bot]' && !contains(github.event.head_commit.message, '[skip-truth-loop]')
    steps:
      - name: Checkout Repository
        uses: actions/checkout@v4
        with:
          fetch-depth: 0
          token: ${{ secrets.GITHUB_TOKEN }}

      - name: Setup Node.js
        uses: actions/setup-node@v4
        with:
          node-version: '20'

      - name: Process Runs and Truth Gates
        id: run-truth
        run: |
          node -e "
          const fs = require('fs');
          const path = require('path');
          const { initializeRunChallenges, verifyRunRepairs } = require('./ChatMachines/GeminiSupervisor/scripts/truth-challenge-engine.js');

          const runsRoot = path.join(process.cwd(), 'ChatMachines/GeminiSupervisor/runs');
          if (!fs.existsSync(runsRoot)) {
            console.log('No runs directory found.');
            process.exit(0);
          }

          const runDirs = fs.readdirSync(runsRoot, { withFileTypes: true }).filter(d => d.isDirectory()).map(d => d.name);
          let stateChanged = false;

          for (const nonce of runDirs) {
            const runPath = path.join(runsRoot, nonce);
            const formPath = path.join(runPath, 'step-0-form.json');
            const truthDir = path.join(runPath, 'truth-reader');
            const passPath = path.join(truthDir, 'PASS.json');
            const manifestPath = path.join(truthDir, 'manifest.json');

            if (fs.existsSync(passPath)) {
              continue;
            }

            if (fs.existsSync(formPath) && !fs.existsSync(manifestPath)) {
              const form = JSON.parse(fs.readFileSync(formPath, 'utf8'));
              const selections = form.worker_editable?.document_selection || {};
              const selectedDocs = Object.keys(selections).filter(k => selections[k] === true);
              if (selectedDocs.length > 0) {
                console.log('Initializing truth challenges for nonce: ' + nonce + ' with docs: ' + selectedDocs.join(', '));
                initializeRunChallenges(nonce, selectedDocs);
                stateChanged = true;
              }
            } else if (fs.existsSync(manifestPath)) {
              console.log('Verifying truth repairs for nonce: ' + nonce);
              const res = verifyRunRepairs(nonce);
              if (res.success) {
                console.log('PASS confirmed for run: ' + nonce);
                stateChanged = true;
              } else {
                console.log('Repair verification FAILED for run: ' + nonce + ' - ' + JSON.stringify(res.errors));
                stateChanged = true;
              }
            }
          }
          fs.writeFileSync('truth_changed.flag', stateChanged ? 'true' : 'false');
          "

      - name: Commit and Push Truth Gate Updates
        run: |
          CHANGED=$(cat truth_changed.flag || echo 'false')
          if [ "$CHANGED" = "true" ]; then
            git config user.name "github-actions[bot]"
            git config user.email "github-actions[bot]@users.noreply.github.com"
            git add ChatMachines/GeminiSupervisor/runs/
            if ! git diff --cached --quiet; then
              git commit -m "chore(truth-reader): process run challenges and repairs [skip-truth-loop]"
              git push
            fi
          else
            echo "No truth reader state mutations."
          fi"
    },
